from pathlib import Path
import re

# Bump only sandbox-kit module require versions v0.1.5 -> v0.1.6
# Keep providers/blaxel at v0.1.0
pat = re.compile(
    r'(github\.com/sandbox-kit/kit/sdks/go/(?:internal/contracts|internal/sdk|sandbox|providers/daytona|providers/modal)) v0\.1\.5'
)

changed = []
for path in Path('.').rglob('go.mod'):
    if 'node_modules' in path.parts:
        continue
    text = path.read_text()
    new, n = pat.subn(r'\1 v0.1.6', text)
    if n:
        path.write_text(new)
        changed.append((str(path), n))

# go.work versioned replaces
work = Path('go.work')
w = work.read_text()
w2 = w.replace(
    'replace github.com/sandbox-kit/kit/sdks/go/internal/contracts v0.1.5 => ./sdks/go/internal/contracts',
